import Foundation

/// Facts read from YouTube's auto-generated art-track description ("Provided to YouTube by ...").
struct ProvidedToYouTubeDescription: Equatable, Sendable {
    /// The distributor named in the header line; it is often not the label.
    var provider: String?
    var title: String
    var artists: [String]
    var album: String?
    var phonogramLine: String?
    var copyrightLine: String?
    var releasedOn: String?
    var releaseDate: Date?
    var credits: [TrackDetails.Credit]

    /// The label named after the year in the phonogram line: "℗ 2013 T-Series" gives "T-Series".
    var label: String? {
        guard let phonogramLine else { return nil }
        var rest = phonogramLine.hasPrefix("\u{2117}") ? String(phonogramLine.dropFirst()) : String(phonogramLine.dropFirst(3))
        rest = rest.trimmingCharacters(in: .whitespaces)
        if let range = rest.range(of: #"^[0-9]{4}(\s*-\s*[0-9]{4})?\s+"#, options: .regularExpression) { rest.removeSubrange(range) }
        let label = rest.trimmingCharacters(in: .whitespacesAndNewlines)
        return label.isEmpty || label.count > 120 ? nil : label
    }
}

/// Pure line parser for YouTube's art-track description. Ordinary uploads return nil.
enum ProvidedToYouTubeDescriptionParser {
    static let header = "Provided to YouTube by"
    private static let footer = "auto-generated by youtube"
    private static let middleDot = " \u{00B7} "
    private static let maximumLines = 400

    static func parse(_ text: String?) -> ProvidedToYouTubeDescription? {
        guard let text, text.utf8.count <= TrackDetails.maximumDescriptionBytes * 4 else { return nil }
        let lines = text.replacingOccurrences(of: "\r\n", with: "\n").replacingOccurrences(of: "\r", with: "\n")
            .split(separator: "\n", omittingEmptySubsequences: false)
            .prefix(maximumLines)
            .map { $0.trimmingCharacters(in: .whitespaces) }
            .filter { !$0.isEmpty }
        guard let first = lines.first, first.lowercased().hasPrefix(header.lowercased()) else { return nil }
        let provider = CatalogText.clean(String(first.dropFirst(header.count)))

        var content = lines.dropFirst().makeIterator()
        guard let titleLine = content.next(), !isFooter(titleLine) else { return nil }
        let segments = titleLine.components(separatedBy: middleDot).map { $0.trimmingCharacters(in: .whitespaces) }.filter { !$0.isEmpty }
        guard let title = segments.first else { return nil }
        var result = ProvidedToYouTubeDescription(provider: provider, title: title, artists: Array(segments.dropFirst()), credits: [])

        var expectsAlbum = true
        while let line = content.next() {
            if isFooter(line) { break }
            if line.hasPrefix("\u{2117}") || line.lowercased().hasPrefix("(p) ") {
                result.phonogramLine = result.phonogramLine ?? line
                expectsAlbum = false
            } else if line.hasPrefix("\u{00A9}") || line.lowercased().hasPrefix("(c) ") {
                result.copyrightLine = result.copyrightLine ?? line
                expectsAlbum = false
            } else if let value = releasedOn(in: line) {
                result.releasedOn = result.releasedOn ?? value
                result.releaseDate = result.releaseDate ?? TrackDetails.date(from: value)
                expectsAlbum = false
            } else if let roleLine = roleLine(line), !expectsAlbum || hasKnownRole(roleLine.roles) {
                expectsAlbum = false
                let names = split(names: roleLine.names)
                for raw in roleLine.roles {
                    for role in TrackDetails.CreditRole.from(providerRole: raw) { TrackDetails.add(role, names: names, to: &result.credits) }
                }
            } else if expectsAlbum {
                // The album is the only free-text line, and it can only follow the title line.
                result.album = line
                expectsAlbum = false
            }
        }
        if let label = result.label { TrackDetails.add(.label, names: [label], to: &result.credits) }
        return result
    }

    private static func isFooter(_ line: String) -> Bool {
        line.lowercased().trimmingCharacters(in: CharacterSet(charactersIn: ". ")).hasPrefix(footer)
    }

    private static func releasedOn(in line: String) -> String? {
        let lowered = line.lowercased()
        guard lowered.hasPrefix("released on") else { return nil }
        let rest = line.dropFirst("released on".count).trimmingCharacters(in: .whitespaces)
        guard rest.hasPrefix(":") else { return nil }
        return CatalogText.clean(String(rest.dropFirst()))
    }

    /// "Associated  Performer, Producer: Ed O'Brien" is two roles; the double space joins one DDEX role's words.
    private static func roleLine(_ line: String) -> (roles: [String], names: String)? {
        guard let colon = line.range(of: ": "), !line.contains(middleDot) else { return nil }
        let rolePart = String(line[..<colon.lowerBound])
        let names = line[colon.upperBound...].trimmingCharacters(in: .whitespaces)
        guard !rolePart.isEmpty, rolePart.count <= 80, !names.isEmpty,
              rolePart.contains(where: \.isLetter), !rolePart.contains(where: \.isNumber) else { return nil }
        let roles = rolePart.split(separator: ",").map { $0.split(whereSeparator: \.isWhitespace).joined(separator: " ") }
            .filter { !$0.isEmpty }
        guard !roles.isEmpty, roles.count <= 6 else { return nil }
        return (roles, names)
    }

    private static func hasKnownRole(_ roles: [String]) -> Bool {
        roles.contains { role in
            TrackDetails.CreditRole.from(providerRole: role).contains { if case .other = $0 { return false } else { return true } }
        }
    }

    static func split(names text: String) -> [String] {
        text.replacingOccurrences(of: " & ", with: ", ").components(separatedBy: ", ")
            .map { $0.trimmingCharacters(in: .whitespaces) }.filter { !$0.isEmpty }
    }
}
